import hashlib, re

def canonical(s):
    return ' '.join(s.split())

def shingles(s, n=2):
    w = canonical(s).split()
    return set(tuple(w[i:i+n]) for i in range(len(w)-n+1))

def jaccard(a, b):
    A, B = shingles(a), shingles(b)
    return len(A & B) / len(A | B) if (A | B) else 1.0

A = 'the river runs beside the old bridge'
B = 'the river runs beside the stone bridge'
C = 'the   river runs beside the old bridge'
digest = lambda s: hashlib.sha256(canonical(s).encode()).hexdigest()
assert digest(A) == digest(C) and digest(A) != digest(B)
assert jaccard(A, B) == 0.5
unique = {digest(s):s for s in (A, B, C)}
assert len(unique) == 2
family = {'a1':'bridge-report', 'a2':'bridge-report', 'b1':'road-report'}
